style.css:
@-moz-document domain("youtube.com") {
/* Fuerza 6 columnas en la cuadrícula principal */
  ytd-rich-grid-renderer {
    display: grid !important;
    grid-template-columns: repeat(6, 1fr) !important;
    column-gap: 16px !important;
    row-gap: 24px !important;
    justify-content: center !important;
  }

  /* Elimina animaciones para mejorar rendimiento */
  * {
    transition: none !important;
    animation: none !important;
    box-shadow: none !important;
  }

  /* Fondo oscuro elegante */
  body {
    background-color: #0f0f0f !important;
    color: #ffffff !important;
  }

  /* Ajuste para monitores ultrapanorámicos */
  ytd-page-manager {
    max-width: 100% !important;
    margin: 0 auto !important;
    padding: 0 40px !important;
  }

  /* Oculta Shorts y elementos no deseados */
  ytd-rich-section-renderer,
  ytd-reel-shelf-renderer {
    display: none !important;
  }

  /* Estilo limpio para los títulos */
  #video-title {
    font-size: 14px !important;
    font-weight: 500 !important;
    color: #e0e0e0 !important;
  }

  /* Menú lateral compacto */
  ytd-mini-guide-renderer {
    width: 60px !important;
  }

  /* Elimina bordes innecesarios */
  ytd-app {
    border: none !important;
  }
}
